// План specs/job-closed-date.md 1.2–1.3 (кейсы JC-04, JC-05). Admin, компания «test». Только просмотр списка Jobs.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import { setLanguage } from '../admin-plans/plans-helpers';
import { cellValue, columnIndex } from '../admin-plans/plans-read-helpers';
import { OLD_COMPLETED_JOBS, jobRow, openJobsTab } from './closed-helpers';

test.use({ storageState: ADMIN_STATE });

const LANGS = [
  { lang: 'en' as const, tab: 'Completed', closed: 'Closed', scheduled: 'Scheduled' },
  { lang: 'he' as const, tab: 'הסתיימו', closed: 'נסגרה', scheduled: 'מתוזמן' },
];

test.describe('Работа: колонка Closed у старых закрытых работ (#94c08102)', () => {
  for (const l of LANGS) {
    test(`Jobs → Completed (${l.lang.toUpperCase()}): column "${l.closed}" after "${l.scheduled}", jobs closed before the change show "-" #94c08102 @desktop @prod-safe`, async ({ page }) => {
      await setLanguage(page, l.lang);
      await openJobsTab(page, l.tab);

      // Колонка есть и стоит сразу после «Scheduled» (источник: «מה רצוי» — עמודה ברשימת העבודות).
      expect(await columnIndex(page, l.closed)).toBe((await columnIndex(page, l.scheduled)) + 1);

      // Старые работы: «-» (комментарий программиста — дату не угадываем).
      for (const job of OLD_COMPLETED_JOBS) {
        await expect(jobRow(page, job), `${job} во вкладке ${l.tab}`).toBeVisible();
        expect(await cellValue(page, jobRow(page, job), l.closed), `${l.closed} у ${job}`).toBe('-');
      }
    });
  }
});
